import fs from "fs"
import path from "path"

/**
 * Keeps the organisation dropdown of the "Submit an event" issue form (.github/ISSUE_TEMPLATE/new-event.yml) in
 * sync with src/content/orgs. The options sit between two marker comments and are regenerated by
 * `npm run update-issue-template`, by OrgWriter whenever the CLI creates an org, and by `make create-org`.
 */

export const ISSUE_TEMPLATE_PATH = path.join(".github", "ISSUE_TEMPLATE", "new-event.yml")
export const NEW_ORG_OPTION = "My organisation isn't listed (new organisation)"

const BEGIN_MARKER = "# BEGIN org options (generated by `npm run update-issue-template`, don't edit by hand)"
const END_MARKER = "# END org options"

export interface OrgOption {
  id: string
  title: string
}

/** Every org folder with its frontmatter title, sorted by title. */
export function getOrgOptions(orgsDir: string): OrgOption[] {
  return fs
    .readdirSync(orgsDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && !entry.name.startsWith("."))
    .filter((entry) => fs.existsSync(path.join(orgsDir, entry.name, "index.md")))
    .map((entry) => {
      const content = fs.readFileSync(path.join(orgsDir, entry.name, "index.md"), "utf8").replace(/\r\n/g, "\n")
      const frontmatter = content.match(/^---\n([\s\S]*?)\n---/)?.[1] ?? ""
      const title =
        frontmatter
          .match(/^title:\s*(.*)$/m)?.[1]
          .trim()
          .replace(/^(["'])(.*)\1$/, "$2") || entry.name
      return { id: entry.name, title }
    })
    .sort((a, b) => a.title.localeCompare(b.title, "en", { sensitivity: "base" }) || a.id.localeCompare(b.id))
}

/** The dropdown text for an org; the ID goes last in parentheses so it can be read back (orgIdFromOption). */
export function orgOptionLabel(org: OrgOption): string {
  return `${org.title} (${org.id})`
}

/** The org ID in a dropdown answer, or null for NEW_ORG_OPTION or text that isn't an option. */
export function orgIdFromOption(option: string): string | null {
  if (option.trim() === NEW_ORG_OPTION) return null
  return option.match(/\(([A-Za-z0-9_-]+)\)\s*$/)?.[1] ?? null
}

/** Replaces the generated options in the template's text. Throws if the markers are missing. */
export function renderIssueTemplate(template: string, orgs: OrgOption[]): string {
  const begin = template.indexOf(BEGIN_MARKER)
  const end = template.indexOf(END_MARKER)
  if (begin === -1 || end === -1 || end < begin) throw new Error(`Org option markers not found in the issue template`)

  const lineStart = template.lastIndexOf("\n", begin) + 1
  const indent = template.slice(lineStart, begin)
  // JSON strings are valid YAML scalars, so titles with quotes or colons need no special handling
  const options = [...orgs.map(orgOptionLabel), NEW_ORG_OPTION].map((label) => `${indent}- ${JSON.stringify(label)}\n`)
  return template.slice(0, begin) + BEGIN_MARKER + "\n" + options.join("") + indent + template.slice(end)
}

/** Rewrites the issue template from the orgs folder. Returns whether the file changed. */
export function updateIssueTemplate(rootDir = process.cwd()): boolean {
  const templatePath = path.join(rootDir, ISSUE_TEMPLATE_PATH)
  const current = fs.readFileSync(templatePath, "utf8")
  const updated = renderIssueTemplate(current, getOrgOptions(path.join(rootDir, "src", "content", "orgs")))
  if (updated === current) return false
  fs.writeFileSync(templatePath, updated, "utf8")
  return true
}
